#define ESPURE_HOMOGRAPH_COUNT 33

#include <string.h>

/**
 * @brief Lookup default IPA for a heterophonic homograph (binary search in Flash)
 */
static inline const char* espure_get_homograph_default(const char* word) {
    if (!word) return NULL;
    int low = 0;
    int high = ESPURE_HOMOGRAPH_COUNT - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        int cmp = strcmp(word, ESPURE_HOMOGRAPH_TABLE[mid].word);
        if (cmp == 0) {
            return ESPURE_HOMOGRAPH_TABLE[mid].default_ipa;
        } else if (cmp < 0) {
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return NULL;
}

